import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'
import type { Recap, Rerun, View } from '../types'
import { alertsOf, applyGoal, bandOf, compactIn, empty, GOAL_SYSTEM, GOAL_TOKENS, goalPrompt, goalWorthy, isNoise, isQuery, mergeShellEdits, recapNotes, recordTurn, reduce, replay, snapshotOf, splitChecks, turnsLeft, whoOf, type SessionModel, type Seen } from './model'
import { draw, type Act, type Els } from './views'

// A pane that answers four questions about the session: what are we trying to do, what is Claude doing, what can it
// see, and what has changed. One `*` hook folds every event into a SessionModel (model.ts); a 2 s clock writes it to
// $.state, which redraws the pane, and to $.store, so a reload or a resume shows the same pane.
// While the pane is hidden, the band above the prompt, toasts and the spinner carry what needs the person (AMBIENT).
// Sections, in order (search `// ===`): STATE, CAPTURE, FLUSH, GOAL, RECAP, RERUN, AMBIENT, HOOKS

// === STATE ===
const PANE = 'session-pane'
const TITLE = 'Session'
const modelAtom = atom({ plugin: 'session-pane', key: 'model' } as const, empty())
const viewAtom = atom({ plugin: 'session-pane', key: 'view' } as const, 'overview' as View)
const helpAtom = atom({ plugin: 'session-pane', key: 'help' } as const, false)
const diffAtom = atom({ plugin: 'session-pane', key: 'diff' } as const, '')
const recapAtom = atom({ plugin: 'session-pane', key: 'recap' } as const, { status: 'idle', text: '' } as Recap)
const rerunAtom = atom({ plugin: 'session-pane', key: 'rerun' } as const, { busy: false } as Rerun)
const shownAtom = atom({ plugin: 'session-pane', key: 'shown' } as const, false) // the pane is open: the band and toasts stay quiet

let m: SessionModel = empty()
let dirty = false // an event changed m since the last flush
let ready: Promise<void> | undefined // restore has run for this session
let early: Seen[] | undefined = [] // events seen before restore finished, folded again onto what it restores
let sid: string | undefined
let shellSince: number | undefined // when the earliest Bash call that finished since the last scan began
let shellUntil = 0 // when the latest of them ended
let endedSid: string | undefined // the session a /clear or a resume ended: restore waits until the id has moved on
let cleared = false // the session being restored began with a /clear: empty, so every event since is in early
let told = new Set<string>() // alertsOf keys already toasted and still holding
let goalQueue: { text: string; from: string }[] = [] // your messages the goal has not seen yet, newest last
let goalBusy = false
let turnOwed = false // a turn ended and its window is not yet recorded for the turns-left estimate
let timer: Timer | undefined

const KEEP_SESSIONS = 20 // snapshots kept in $.store; the oldest goes when a new session writes its first
const SLACK_MS = 2000 // a file's mtime may fall this far outside the calls' span and still count as written by them
const MAX_STATS = 200 // dirty files looked at per scan: a repo with thousands untracked costs no more than this
const REPLAYED = new Set(['prompt.submit', 'tool.call']) // what replay() rebuilds from a transcript
const MAX_GOAL_QUEUE = 5 // messages one goal call reads: older ones are what the newest build on
const MAX_EARLY = 500 // events held while restore can't run (session.id failing): enough for a slow start, not a leak
const snapKey = (id: string) => `snap:${id}`

// === CAPTURE ===
// The * hook: fold the event in before the chain runs and again with its result. It never changes e or the result, never
// writes state (a redraw is an event: writing from here would loop), and a failure of its own never reaches the chain.
// Declared at the top level: the loader only takes a hook it can see declared there
async function capture($: EngineInterface, e: unknown, next: any) {
  if (next.is('engine.create', e)) return next(e) // $ is the empty table there
  const ev: string = next.event
  const origin = next.origin
  // our own $ calls (model.complete, store.set, fs.read) and other plugins' polling never move the pane
  if (origin.plugin === PANE || isNoise(ev) || (origin.plugin !== 'engine' && isQuery(ev))) return next(e)
  const t0 = Date.now()
  fold({ ev, ph: 'enter', who: whoOf(ev, origin, e), e, t: t0 })
  let r: unknown
  try { r = await next(e) } catch (err) {
    fold({ ev, ph: 'exit', who: whoOf(ev, origin, e, 'exit'), e, r: undefined, t: Date.now() }) // a thrown call still stops waiting
    throw err
  } finally {
    if (ev === 'tool.call' && (e as any)?.tool === 'Bash') { shellSince = Math.min(shellSince ?? t0, t0); shellUntil = Date.now() } // scanned by the clock, never here
  }
  fold({ ev, ph: 'exit', who: whoOf(ev, origin, e, 'exit'), e, r, t: Date.now() })
  return r
}

function fold(x: Seen) {
  try {
    if (early) { early.push(x); if (early.length > MAX_EARLY) early.shift() }
    const worthy = x.ev === 'prompt.submit' && x.who === 'you' && goalWorthy(m, String(x.e?.text ?? '')) // before reduce drafts a goal
    if (!reduce(m, x)) return
    dirty = true
    // queued, never asked here: the clock asks, and only while the pane is open (askGoal)
    if (worthy) goalQueue = queueGoal(goalQueue, { text: m.lastPrompt ?? '', from: m.prompts === 1 ? 'Your opening message' : `Your message ${m.prompts}` })
    if (x.ev === 'turn.complete' && !x.e?.agentId) turnOwed = true // a main turn ended, not a subagent's: the clock reads its window
  } catch {}
}

// === FLUSH ===
// Brings back this session's model: from $.state after a hot reload (it keeps the diffs), else the $.store snapshot after a
// restart, else the transcript of a resumed session. Events seen meanwhile are folded again on top
async function restore($: EngineInterface): Promise<void> {
  const id = await $.session.id()
  if (id === endedSid) throw new Error('the ended session is still current') // the next flush tries again
  let got: SessionModel | undefined
  const held = await read($, modelAtom).catch(() => undefined)
  if (held?.sessionId === id) got = { ...empty(), ...held } // a field this load added is missing from what the last one held
  if (!got) {
    const snap = await $.store.get(snapKey(id)).catch(() => undefined) as SessionModel | undefined
    if (snap && typeof snap === 'object' && snap.sessionId === id) got = { ...empty(), ...snap }
  }
  let replayed = false
  if (!got) {
    got = empty()
    const msgs = cleared ? [] : await $.session.messages().catch(() => [])
    if (msgs.length) { replay(got, msgs); replayed = true }
  }
  got.sessionId = id
  // the transcript, read just now, already holds the prompts and tool calls seen meanwhile: folded again they would count twice
  for (const x of early ?? []) if (!replayed || !REPLAYED.has(x.ev)) reduce(got, x)
  early = undefined
  cleared = false
  m = got
  sid = id
  dirty = true
  told = new Set(alertsOf(m).keys()) // what held before a restart or a resume was announced then, or is stale news now
  // a draft never condensed (a replayed transcript, a call cut short by a restart) is asked about when the pane is next open
  const g = m.goal
  if (g?.isDraft && !goalQueue.some(q => q.text === g.text)) goalQueue = [{ text: g.text, from: g.from }, ...goalQueue]
  // per session: the session after a /clear or a resume needs it again
  await $.command.register({ name: 'session-pane', description: 'Show or hide the session pane: your goal, changes so far and whether checks still hold, what needs you, and context.' })
    .catch(err => { $.ui.log(`session-pane: /session-pane could not be registered: ${err}`) })
}

let flushing: Promise<void> | undefined
async function flushOnce($: EngineInterface): Promise<void> {
  await (ready ??= restore($).catch(() => { ready = undefined })) // failed (session.id rejected): the next flush tries again
  if (!sid) return
  if (shellSince !== undefined) {
    const since = shellSince
    shellSince = undefined
    // each at its own mtime, not the scan's: a check that ran after the edit stays current
    for (const f of await shellEdits($, since, shellUntil).catch(() => [])) if (mergeShellEdits(m, [f.path], f.t)) dirty = true
  }
  if (turnOwed) {
    turnOwed = false
    // 'summary' counts locally from the last response, no request sent; the threshold is in the same tokens as the total
    const b = (await $.session.usage({ breakdown: 'summary' }).catch(() => undefined))?.context.breakdown
    if (b) { recordTurn(m, b.totalTokens, b.isAutoCompactEnabled ? b.autoCompactThreshold : undefined); dirty = true }
  }
  if (goalQueue.length && !goalBusy && await read($, shownAtom).catch(() => false)) void askGoal($)
  if (!dirty) return
  dirty = false
  const plain = JSON.parse(JSON.stringify(m)) as SessionModel // a copy: the live model keeps changing under the write
  await update($, modelAtom, () => plain)
  await announce($)
  await remember($, snapshotOf(plain))
}
// Which files a shell command wrote is not in any event: the Bash call carries its command and output only. So, as a
// guess: every modified or untracked (not ignored) file in the session's repo whose mtime falls between the first
// scanned call's start and the last one's end. A write by someone else in that window is credited to the session; a
// repo other than the session's is not looked at. No git, no repo or no $.process (a surface other than the CLI): nothing
async function shellEdits($: EngineInterface, since: number, until: number): Promise<{ path: string; t: number }[]> {
  const top = await $.process.run(['git', 'rev-parse', '--show-toplevel'], { timeoutMs: 5000 })
  if (top.exitCode !== 0) return []
  const root = top.stdout.trim()
  const ls = await $.process.run(['git', 'ls-files', '-z', '-m', '-o', '--exclude-standard'], { cwd: root, timeoutMs: 10_000 })
  if (ls.exitCode !== 0) return []
  const paths = [...new Set(ls.stdout.split('\0').filter(Boolean))].slice(0, MAX_STATS).map(p => `${root}/${p}`)
  const stats = await Promise.all(paths.map(p => $.fs.stat(p).then(s => s.mtimeMs, () => 0)))
  return paths.map((path, i) => ({ path, t: stats[i] ?? 0 })).filter(f => f.t >= since - SLACK_MS && f.t <= until + SLACK_MS)
}

const flush = ($: EngineInterface) => flushing ??= flushOnce($).finally(() => { flushing = undefined })

async function remember($: EngineInterface, snap: SessionModel) {
  if (!sid) return
  await $.store.set(snapKey(sid), snap)
  const recent = ((await $.store.get('recent').catch(() => undefined)) as string[] | undefined) ?? []
  if (recent[0] === sid) return
  const next = [sid, ...recent.filter(x => x !== sid)]
  for (const old of next.slice(KEEP_SESSIONS)) await $.store.delete(snapKey(old)).catch(() => {})
  await $.store.set('recent', next.slice(0, KEEP_SESSIONS))
}

// === GOAL ===
// The oldest message (often the one that set the goal) and the newest after it: what one call reads
const queueGoal = (q: typeof goalQueue, x: (typeof goalQueue)[number]) => { const n = [...q, x]; return n.length > MAX_GOAL_QUEUE ? [n[0]!, ...n.slice(-(MAX_GOAL_QUEUE - 1))] : n }
// The goal costs nothing while the pane is hidden: messages queue, and one call condenses all of them once the pane is
// open (on opening, then at most one per clock tick while it stays open). A failed call leaves the goal as it was
async function askGoal($: EngineInterface) {
  goalBusy = true
  try {
    while (goalQueue.length) {
      const batch = goalQueue
      goalQueue = []
      const last = batch.at(-1)!
      const at = sid
      const r = await $.model.complete({ model: 'haiku', system: GOAL_SYSTEM, prompt: goalPrompt(m, batch.map(b => b.text)), maxTokens: GOAL_TOKENS, timeoutMs: 20_000 }).catch(() => undefined)
      if (sid !== at) return // a /clear or a resume moved on: the answer is about the session before
      if (r?.isAnswered && applyGoal(m, r.text, last.text, last.from)) dirty = true
    }
  } finally { goalBusy = false }
}

// === RECAP ===
const RECAP_PROMPT = `Write a recap of this session so far, for continuing the work after older details are summarised.
Use these headings, each with short plain bullet points: Goal; Preferences and constraints; Decisions made; Progress so far; Still to do.
Only include what this conversation actually established. At most 250 words. No preamble.`

async function draftRecap($: EngineInterface) {
  const at = sid
  await update($, recapAtom, () => ({ status: 'drafting', text: '' }))
  // what the pane folded from this session's events: a seed for what a summary may have dropped, not the source of truth
  const notes = recapNotes(m)
  const prompt = notes ? `${RECAP_PROMPT}\n\nNotes the session pane kept, which may help:\n<notes>\n${notes.slice(0, 6000)}\n</notes>` : RECAP_PROMPT
  const r = await $.model.fork({ prompt }).catch(err => ({ isAnswered: false as const, reason: String(err) }))
  if (sid !== at) return // a /clear or a resume moved on: this recap is of the session before, never to be used on this one
  const next: Recap = r.isAnswered ? { status: 'ready', text: r.text.trim() }
    : { status: 'failed', text: '', note: r.reason === 'nothing-to-fork' ? 'Nothing to recap yet: send a message first.' : "Couldn't draft a recap. Try again in a moment." }
  await update($, recapAtom, () => next)
  // drafting takes a while: the person may have hidden the pane meanwhile
  if (next.status === 'ready' && !(await read($, shownAtom))) $.ui.toast('Recap ready: /session-pane to review it')
}

async function useRecap($: EngineInterface) {
  const r = await read($, recapAtom)
  if (r.status !== 'ready') return
  await update($, recapAtom, () => ({ ...r, status: 'applying' }))
  const before = m.compactions
  const res = await $.session.compact({ instructions: `Carry this recap, reviewed by the person, into the summary faithfully:\n\n${r.text}` }).catch(err => ({ skip: String(err) }))
  // our own $ call: capture skips its events, so the compaction is folded here, unless capture saw it after all
  if (!res.skip && m.compactions === before) fold({ ev: 'session.compact', ph: 'exit', who: 'engine', e: { trigger: 'plugin' }, r: res, t: Date.now() })
  await update($, recapAtom, () => res.skip ? { ...r, status: 'failed', note: "The summary didn't run. Try again in a moment." } : { ...r, status: 'applied' })
}

// === RERUN ===
// Stale checks run again on the person's press, each command as Claude ran it (only those kept unaltered: canRerun).
// Through $.tool.call, so the permission check applies; capture skips our own calls, so each result is folded here
async function rerunStale($: EngineInterface) {
  const stale = splitChecks(m).stale.filter(c => c.canRerun)
  const cmds = [...new Map(stale.map(c => [c.cmd, c.name])).entries()] // two checks in one command run it once
  if (!cmds.length || (await read($, rerunAtom)).busy) return
  await update($, rerunAtom, () => ({ busy: true }))
  const at = sid
  let note: string | undefined
  for (const [command, name] of cmds) {
    const e = { tool: 'Bash' as const, command, description: `Rerun ${name}` }
    const r = await $.tool.call(e).catch(err => ({ deny: String(err) }))
    if (sid !== at) return // a /clear or a resume moved on: the result is the session before's, and session.end reset busy
    if (r.deny) { note = `${name} was not rerun: ${r.deny}`; break }
    fold({ ev: 'tool.call', ph: 'exit', who: `plugin:${PANE}`, e: { ...e, tool_use_id: `rerun-${Date.now()}` }, r, t: Date.now() })
  }
  await flush($).catch(() => {}) // the checks redraw fresh with the button's return, not a clock tick later
  await update($, rerunAtom, () => ({ busy: false, note, at: Date.now() }))
}

// === AMBIENT ===
// A toast per alert as it appears, only between turns: a check that fails mid-turn is Claude's to fix, and a toast for it
// would be stale before it was read. Held while the pane is open, which shows the same
async function announce($: EngineInterface) {
  const now = alertsOf(m)
  for (const k of told) if (!now.has(k)) told.delete(k) // cleared: the next time it holds is news again
  if (m.running || await read($, shownAtom).catch(() => false)) return
  for (const [k, text] of now) if (!told.has(k)) { told.add(k); $.ui.toast(text) }
}

// === HOOKS ===
export const register: Register = on => {
  on('*', capture)

  // Once per process and per fresh load of this module, never after a /clear or a resume: session.end starts those over.
  // A reload finds its own session in $.state
  on('session.start', async ($, e, next) => {
    timer ??= $.clock.every(2000, () => { flush($).catch(() => {}) })
    await (ready ??= restore($).catch(() => { ready = undefined }))
    return next(e) // never opens the pane: only /session-pane does
  })

  on('session.end', async ($, e, next) => {
    shellSince = undefined // the exit's time bound is short and shared: no git scan now
    try { await flush($); await flush($) } catch {} // the second catches changes made while an in-flight flush was writing
    if (e.reason === 'clear' || e.reason === 'resume') {
      // the process goes on under a new session id and no session.start follows: the clock keeps running, and its next
      // flush restores the new session once the id has moved on
      endedSid = e.sessionId; cleared = e.reason === 'clear'
      m = empty(); ready = undefined; sid = undefined; early = []; goalQueue = []; dirty = false; turnOwed = false; told = new Set()
      await Promise.all([update($, modelAtom, () => empty()), update($, viewAtom, () => 'overview'), update($, diffAtom, () => ''), update($, recapAtom, () => ({ status: 'idle', text: '' })), update($, rerunAtom, () => ({ busy: false }))]).catch(() => {})
    } else { timer?.cancel(); timer = undefined }
    return next(e)
  })

  on('command.run', { command: 'session-pane' }, async $ => {
    const up = (await $.ui.panes()).some(p => p.id === PANE)
    if (up) { await $.ui.close({ id: PANE }); await update($, shownAtom, () => false); return { text: 'Session pane hidden' } }
    await flush($).catch(() => {})
    // docked, the default share is far wider than the ~44 columns the pages are laid out for and squeezes the transcript;
    // 48 leaves a few over, so a long label wraps less. A request only: a width the person dragged the dock to wins
    await $.ui.open({ id: PANE, title: TITLE, focus: true, columns: 48 })
    await update($, shownAtom, () => true)
    if (goalQueue.length && !goalBusy) void askGoal($) // what was said while it was hidden, in one call
    return { text: 'Session pane shown' }
  })

  on('ui.close', async ($, e, next) => {
    if (e.id === PANE) await Promise.all([update($, viewAtom, () => 'overview'), update($, shownAtom, () => false)]).catch(() => {}) // reopened, it starts at the overview
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const el = $.ui.resolve(e) as Els
    const [model, view, help, diff, recap, rerun] = await Promise.all([read($, modelAtom), read($, viewAtom), read($, helpAtom), read($, diffAtom), read($, recapAtom), read($, rerunAtom)])
    const usage = view === 'context' ? await $.session.usage({ breakdown: 'summary' }).catch(() => undefined)
      : view === 'details' ? await $.session.usage().catch(() => undefined) : undefined
    const name = view === 'details' ? await $.session.model().catch(() => undefined) : undefined
    const act: Act = {
      go: v => { void update($, viewAtom, () => v) },
      help: () => { void update($, helpAtom, h => !h) },
      diff: path => { void update($, diffAtom, () => path).then(() => update($, viewAtom, () => 'diff')) },
      draft: () => { void draftRecap($).catch(() => {}) },
      use: () => { void useRecap($).catch(() => {}) },
      discard: () => { void update($, recapAtom, () => ({ status: 'idle', text: '' })) },
      rerun: () => { void rerunStale($).catch(() => update($, rerunAtom, () => ({ busy: false }))) },
    }
    return draw(el, { m: model, view, help, diff, recap, rerun, cols: e.props.bodyColumns ?? 44, usage, model: name }, act)
  })

  // The band above the prompt, shared with other mods: theirs stays, ours goes on top. Between turns only, and only while
  // something needs the person; a survey holds the band alone
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const theirs = await next(e)
    if (e.props.hasSurvey || e.props.isWorking || await read($, shownAtom)) return theirs
    const parts = bandOf(await read($, modelAtom))
    if (!parts.length) return theirs
    const { Box, Text } = $.ui.resolve(e) as Els
    const line = (
      // one line, the way in first: a narrow terminal cuts the last alert, never where to look. Dim dots between parts,
      // since two warnings side by side share a colour
      <Text key="session-pane-band" wrap="truncate-end">
        <Text dimColor>/session-pane </Text>
        {parts.flatMap((p, i) => [i ? <Text key={`d${i}`} dimColor> · </Text> : null, <Text key={`p${i}`} color={p.color}>{p.text}</Text>])}
      </Text>
    )
    return theirs ? <Box flexDirection="column">{line}{theirs}</Box> : line
  })

  // During a turn the band is hidden, so the spinner carries the one thing that can't wait for the turn to end
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    const left = turnsLeft(await read($, modelAtom))
    if (left == null || left > 2) return next(e)
    // the engine's suffix may be '' (a message that ends in its own ellipsis): no separator dangling in front then
    return next({ ...e, props: { ...e.props, suffix: [e.props.suffix, compactIn(left).toLowerCase()].filter(Boolean).join(' · ') } })
  })
}

files.hooks/model.ts:
// The session as the pane reads it: one mutable SessionModel, folded from every event the `*` hook sees (reduce), plus
// the pure readings the views draw from it (statusOf, checksOf, contextLabel, segmentsOf). No $ calls here: the hooks
// module owns those, so everything below runs in a test as plain data.
// Sections, in order (search `// ===`): TEXT, WHO, CHECKS, TOOLS, MODEL, REDUCE, READINGS, RESTORE

import type { Agent, Est, FileChange, Goal, Hunk, SessionModel, Source, SourceNote } from '../types'
export type { Agent, Est, FileChange, Goal, Hunk, SessionModel, Source, SourceNote }

// === TEXT ===
// best-effort secret scrub, not a guarantee: anything the pane shows or stores passes through it
// The value after a secret-looking name (`OPENAI_KEY=`, `GH_PAT=`, `Authorization: Basic `, mysql's `-p<pass>`), then
// well-known token shapes wherever they stand (`sk-…`, `ghp_…`, `xoxb-…`, `AKIA…`)
const SECRET_AFTER = /(bearer\s+|basic\s+|\b\w*(token|secret|password|passwd|api[_-]?key|_key|_pat|credential)\w*[=:]\s*|--?(password|token|api-key)[= ]|\b(?:mysql\w*|mariadb)\b[^\n|;&]*?\s-p(?=[^\s-])|:\/\/[^:\/\s]+:)[^\s@'"]+/gi
const SECRET_SHAPE = /\b(sk-|ghp_|gho_|ghs_|ghu_|github_pat_|xox[abpors]-|AKIA)[A-Za-z0-9_-]{12,}/g
export const scrub = (s: string) => s.replace(SECRET_AFTER, '$1***').replace(SECRET_SHAPE, '$1***')
const ANSI = /\x1b\[[0-9;?]*[A-Za-z]/g
export const base = (p: string) => p.replace(/\/+$/, '').split('/').pop() || p
const clip = (s: string, n: number) => s.length > n ? `${s.slice(0, n - 1)}…` : s
const oneLine = (s: string) => s.replace(/\s+/g, ' ').trim()

// === WHO ===
export type Origin = { readonly plugin: string; readonly tier: string }
// prompt origins that are the person: typed (composer), `claude -p` (sdk), remote control (bridge); ui.* events use person
const PERSON = new Set(['person', 'composer', 'sdk', 'bridge'])
export function whoOf(ev: string, origin: Origin, e: any, ph: 'enter' | 'exit' = 'enter'): string {
  if (ev.startsWith('classic.')) return 'hook' // the settings hooks' events
  if (origin.plugin !== 'engine') return `plugin:${origin.plugin}` // its $ call raised it
  if (PERSON.has(e?.origin?.kind)) return 'you'
  const m = e?.message
  if ((ev === 'turn.step' && ph === 'exit') || ev === 'tool.call' || (ev === 'session.append' && (m?.type === 'assistant' || m?.role === 'assistant'))) return 'claude'
  return 'engine'
}

// Never folded: the screen's own events and the composer's keystrokes. session.measure is kept: it is the context fill
const NOISE = new Set(['prompt.edit', 'prompt.autocomplete', 'prompt.suggest'])
export const isNoise = (ev: string) => NOISE.has(ev) || ev.startsWith('ui.') || ev.startsWith('clock.') || ev.endsWith('.describe')
// Read-only queries: another plugin polling them (from its render hook or a timer) must never redraw this pane, else each
// redraw that makes one makes the next
const QUERY = new Set(['ui.panes', 'session.id', 'session.cwd', 'session.root', 'session.repo', 'session.version', 'session.model', 'session.usage', 'session.surfaces', 'session.messages'])
export const isQuery = (ev: string) => QUERY.has(ev) || /\.(get|list|keys|read|exists|stat)$/.test(ev)

// === CHECKS ===
// A Bash call's output read for a verdict: its exit code and the one to three lines that say what failed
const OUTPUT_NOISE = /^\s*(npm (ERR!|error)\s*$|npm (ERR!|error) (code|path|errno|syscall|signal|command|cwd|A complete log|Lifecycle)|at .*(node_modules|node:internal)|[\d.]+%|.*[█░▓▒]{3}|[⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏])/i
const ERRLINE = /(error|exception)\b|\b(fatal|fail(ed|ure)?|panic|denied|rejected|conflict|not found|no such file|cannot|unable)\b|TS\d{4}/i // no \b before error: KeyError, TypeError
const WRAP = new Set(['sudo', 'npx', 'bunx', 'exec', 'time', 'env', 'nice', 'timeout'])
const RUNNER = /^(uv|poetry|pipenv|pdm|rye|hatch)$/ // `uv run pytest`: the program is what it runs
const noCd = (s: string) => s.replace(/^\s*cd\s+\S+\s*(&&|;)\s*/, '') // a Bash command minus its leading `cd <dir> &&` / `;`
export const progOf = (seg: string): string => { // `FOO=1 timeout 30 npx tsc -p .` -> tsc; `npm run test` -> npm test
  const w = seg.trim().split(/\s+/).filter(t => t && !/^\w+=/.test(t))
  while (w.length > 1 && (WRAP.has(w[0]!) || /^\d+[smh]?$/.test(w[0]!))) w.shift()
  const p = (w[0] ?? '').split('/').pop() ?? ''
  if (RUNNER.test(p) && w[1] === 'run' && w[2]) return progOf(w.slice(2).join(' '))
  if (/^python[\d.]*$/.test(p) && w[1] === '-m' && w[2]) return w[2] // python -m pytest -> pytest
  if (/^(pnpm|yarn|bun)$/.test(p) && (w[1] === 'exec' || w[1] === 'dlx') && w[2]) return progOf(w.slice(2).join(' '))
  if ((p === 'make' || p === 'just') && w[1] && !w[1].startsWith('-')) return `${p} ${w[1]}`
  if (/^(npm|pnpm|yarn|bun)$/.test(p) && w[1] && !w[1].startsWith('-')) return `${p} ${w[1] === 'run' ? w[2] ?? 'run' : w[1]}`
  if (p === 'claude' && w[1] === 'plugin' && w[2]) return `claude plugin ${w[2]}` // a plugin's own test and validate
  if ((p === 'cargo' || p === 'go') && w[1]) return `${p} ${w[1]}`
  return p
}
const progsOf = (cmd: string) => noCd(cmd).split(/&&|\|\||[;|\n]/).map(progOf).filter(Boolean)
export function insightOf(cmd: string | undefined, raw: string): { exit?: number; text: string } {
  const m = raw.match(/^Exit code (\d+)/m) // the Bash tool's error text leads with it
  const exit = m ? Number(m[1]) : undefined
  const lines = raw.replace(ANSI, '').split('\n').map(l => l.trimEnd()).filter(l => l.trim() && !/^Exit code \d+$/.test(l.trim()) && !OUTPUT_NOISE.test(l))
  const progs = cmd ? progsOf(cmd) : []
  const last = progs.at(-1)
  const known = progs.find(p => /^(vue-tsc|tsc|vitest|jest|pytest|git|cargo|go|eslint)\b|test$/.test(p)) ?? last ?? ''
  let head = known
  let pick: string[] = []
  const ts = lines.filter(l => /error TS\d+/.test(l))
  if (ts.length) {
    const files = new Set(ts.map(l => l.split('(')[0]))
    head = `${known || 'tsc'}: ${ts.length} error${ts.length > 1 ? 's' : ''} in ${files.size} file${files.size > 1 ? 's' : ''}`
    pick = ts.map(l => l.replace(/^[^(]*\//, '').replace(/:\s*error (TS\d+):\s*/, '  $1 ')) // `src/x.ts(4,7): error TS2322: msg` -> `x.ts(4,7)  TS2322 msg`
  } else if (/test|vitest|jest|pytest/.test(known)) pick = lines.filter(l => /^\s*(FAIL|FAILED|✗|×|●)\s|\b\d+ failed\b|^\(fail\)/.test(l))
  else if (known === 'git') pick = lines.filter(l => /^(fatal|error):|\[rejected\]|^CONFLICT/.test(l))
  if (!pick.length) pick = lines.filter(l => ERRLINE.test(l))
  if (!pick.length) pick = lines.slice(-3) // errors land at the end more often than at the start
  return { exit, text: scrub([head, ...pick.slice(0, 3).map(l => l.trim())].filter(Boolean).join('\n')).slice(0, 300) }
}

// Which commands count as a check, under which plain name, and which output line says one failed. Matched per program of
// the command, first hit wins; a command that is none of these (a build, a git call) is not a check
const CHECK: [RegExp, string, RegExp][] = [
  [/^(tsc|vue-tsc|mypy|pyright|cargo check|go vet|(npm|pnpm|yarn|bun) (typecheck|type-check|check-types|tsc)|(make|just) (typecheck|type-check))$/, 'Type check', /error TS\d+|^error(\[E\d+\])?:|\b[1-9]\d* errors?\b/],
  [/^(eslint|ruff|biome|shellcheck|cargo clippy|claude plugin validate|(npm|pnpm|yarn|bun) lint|(make|just) lint)$/, 'Lint', /\b[1-9]\d* errors?\b/],
  [/^(vitest|jest|pytest|mocha|playwright|cargo test|go test|claude plugin test|(npm|pnpm|yarn|bun) (test|t|test:\S+)|(make|just) tests?)$/, 'Tests', /^\s*(FAIL|FAILED)\b|^\s*[✗×]\s|\b[1-9]\d* (failed|failing|fail)\b|^\(fail\)/],
]
// isLast: the check is the command's last program, so the command's exit code is the check's own
function checkIn(cmd: string): { name: string; fail: RegExp; isLast: boolean } | undefined {
  const progs = progsOf(cmd)
  for (const [i, p] of progs.entries()) for (const [re, name, fail] of CHECK) if (re.test(p)) return { name, fail, isLast: i === progs.length - 1 }
  return undefined
}
export const checkOf = (cmd: string): string | undefined => checkIn(cmd)?.name

// === TOOLS ===
// What kind of effect a tool call has: Look feeds "Files and references", Change adds to the changes, the rest are results
const KIND: [RegExp, string][] = [
  [/^(Bash|PowerShell)$/, 'Shell'], [/^(Read|Grep|Glob|LS|LSP|NotebookRead)$/, 'Look'], [/^(Edit|Write|NotebookEdit)$/, 'Change'],
  [/^Web/, 'Web'], [/^(Agent|SendMessage|ListAgents|SubagentHandback|Task\w*)$/, 'Agent'], [/^Skill$/, 'Skill'], [/^mcp__/, 'MCP'],
  [/^(EnterWorktree|ExitWorktree|ToolSearch|TodoWrite|EnterPlanMode|ExitPlanMode|AskUserQuestion|SendUserMessage|Monitor|Cron\w*|ScheduleWakeup|RemoteTrigger|ReadNotifications|PushNotification)$/, 'Control'],
]
export const kindOf = (tool: string) => KIND.find(([re]) => re.test(tool))?.[1] ?? 'Tool'
const pathOf = (i: any): string => String(i?.file_path ?? i?.notebook_path ?? i?.path ?? '')

// What a subagent's tool call is doing, in words, present tense. A Bash call's own description says it best
export function doingOf(tool: string, i: any): string {
  const s = (x: unknown) => scrub(oneLine(String(x ?? '')))
  switch (tool) {
    case 'Read': return `Reading ${base(pathOf(i))}`
    case 'Edit': case 'NotebookEdit': return `Editing ${base(pathOf(i))}`
    case 'Write': return `Writing ${base(pathOf(i))}`
    case 'Grep': return `Searching for "${clip(s(i?.pattern), 40)}"`
    case 'Glob': return 'Looking for files'
    case 'Bash': {
      const cmd = String(i?.command ?? '')
      const c = checkOf(cmd)
      return i?.description ? clip(s(i.description), 80) : c ? `Running ${c.toLowerCase()}` : `Running ${progsOf(cmd).at(-1) ?? 'a command'}`
    }
    case 'WebFetch': return `Reading ${s(i?.url).replace(/^https?:\/\//, '').split('/')[0]}`
    case 'WebSearch': return `Searching the web for "${clip(s(i?.query), 40)}"`
    case 'Agent': return `Working with a helper: ${clip(s(i?.description) || 'a task', 60)}`
    case 'Skill': return `Using the ${s(i?.skill)} skill`
    case 'AskUserQuestion': return 'Asking you a question'
    case 'TodoWrite': return 'Updating its plan'
  }
  if (tool.startsWith('mcp__')) { const [, server, name] = tool.split('__'); return `Using ${server}: ${name ?? ''}`.trim() }
  return `Using ${tool}`
}

// === MODEL ===
export const empty = (): SessionModel => ({ prompts: 0, running: false, waits: {}, asking: {}, files: [], checks: [], lastEdit: 0, context: {}, turnTokens: [], est: { conversation: 0, files: 0, results: 0 }, sources: [], compactions: 0, agents: [], onPlan: false })

const MAX_FILES = 50
const MAX_SOURCES = 40
const MAX_AGENTS = 20
// A call's input, held only to match it to its permission request: a digest, never the content (a Write's whole file,
// a command's secrets) in state
const digest = (s: string) => { let h = 2166136261; for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619); return `${s.length}:${(h >>> 0).toString(36)}` }
const MAX_HUNK_LINES = 400 // per file: the diff view shows the change, not a whole generated file

// === REDUCE ===
// One event as the `*` hook saw it. enter: before the chain ran (r undefined); exit: after, with its result
export type Seen = { ev: string; ph: 'enter' | 'exit'; who: string; e: any; r?: any; t: number }

function addSource(m: SessionModel, s: Source) {
  m.sources = [s, ...m.sources.filter(x => x.key !== s.key)].slice(0, MAX_SOURCES)
}
function addFile(m: SessionModel, f: FileChange) {
  const was = m.files.find(x => x.path === f.path)
  const isNew = was ? was.isNew : f.isNew // a file this session created stays New through later edits
  const hunks = capHunks([...(was?.hunks ?? []), ...(f.hunks ?? [])])
  const byShell = f.byShell && (!was || was.byShell) // a tool edit's diff outranks a shell's mention
  m.files = [{ path: f.path, isNew, t: f.t, ...(hunks.length ? { hunks } : {}), ...(byShell ? { byShell: true as const } : {}) }, ...m.files.filter(x => x.path !== f.path)].slice(0, MAX_FILES)
}
// The newest hunks up to the cap, oldest first: the latest change is the one to review. A single hunk over the cap keeps
// its first lines rather than vanishing
function capHunks(all: Hunk[]): Hunk[] {
  const kept: Hunk[] = []
  let n = 0
  for (const h of [...all].reverse()) {
    if (n + h.lines.length > MAX_HUNK_LINES) { if (!kept.length) kept.push({ ...h, lines: h.lines.slice(0, MAX_HUNK_LINES) }); break }
    n += h.lines.length
    kept.push(h)
  }
  return kept.reverse()
}
const hunksOf = (r: any): Hunk[] => Array.isArray(r?.structuredPatch) ? r.structuredPatch.map((h: any) => ({ oldStart: h.oldStart, newStart: h.newStart, lines: (h.lines ?? []).map((l: string) => scrub(String(l))) })) : []

// The question an AskUserQuestion call puts, with its choices; the dialog stays the only place to answer
export function questionOf(i: any): string {
  const q = Array.isArray(i?.questions) ? i.questions[0] : undefined
  if (!q) return 'Claude has a question for you'
  const opts = Array.isArray(q.options) ? q.options.map((o: any) => o?.label).filter(Boolean) : []
  return scrub(oneLine(`${q.question ?? ''}${opts.length ? ` (${opts.join(' / ')})` : ''}`))
}

// Folds one event into m. Returns whether anything the pane draws changed. Subagent calls (agentId) add changes and
// checks; only the main conversation's calls count toward what the context holds
export function reduce(m: SessionModel, x: Seen): boolean {
  const { ev, ph, e, r, t } = x
  if (ev === 'prompt.submit' && ph === 'exit' && x.who === 'you') {
    const text = String(e?.text ?? '').trim()
    if (!text || text.startsWith('/')) return false // a slash command is not a message to Claude
    m.lastPrompt = scrub(text).slice(0, 2000)
    // a free draft at once: the opening message's first sentence, until the small model condenses it
    if (!m.goal) m.goal = { title: titleOf(m.lastPrompt), keep: [], from: 'Your opening message', text: m.lastPrompt, isDraft: true }
    m.prompts++
    m.est.conversation += text.length
    return true
  }
  if (ev === 'turn.start' && ph === 'enter') { m.running = true; m.ended = undefined; return true }
  if (ev === 'agent.spawn' && ph === 'exit' && r?.agentId) {
    m.agents = [{ id: String(r.agentId), name: scrub(String(e?.description || e?.subagentType || 'Subagent')), type: e?.subagentType, status: 'running' as const, calls: 0, t }, ...m.agents].slice(0, MAX_AGENTS)
    return true
  }
  // a second sign a subagent ended, should its turn.complete never come: else it would read as running all session
  if (ev === 'classic.SubagentStop' && ph === 'enter' && e?.agent_id) return agentDid(m, String(e.agent_id), a => a.status === 'running' ? { ...a, status: 'done', doing: undefined } : a)
  if (ev === 'turn.complete' && ph === 'enter') {
    if (e?.agentId) {
      const u = e?.usage
      const tokens = u ? (u.input_tokens ?? 0) + (u.output_tokens ?? 0) + (u.cache_read_input_tokens ?? 0) + (u.cache_creation_input_tokens ?? 0) : undefined
      return agentDid(m, e.agentId, a => ({ ...a, status: e?.isAborted ? 'stopped' : 'done', doing: undefined, tokens: tokens || a.tokens }))
    }
    m.running = false; m.waits = {}; m.asking = {}
    m.ended = e?.isAborted ? 'aborted' : e?.reason
    m.est.conversation += String(e?.answer ?? '').length
    return true
  }
  if (ev === 'tool.check' && ph === 'exit' && r?.decision === 'ask' && e?.tool_use_id) {
    m.asking = { ...m.asking, [e.tool_use_id]: { tool: String(e.tool), input: digest(JSON.stringify(e.input)), text: `Allow: ${doingOf(String(e.tool), e.input)}?` } }
    return false // nothing drawn yet: the classifier may answer it
  }
  // a permission request no settings hook answered: the dialog opens next. It names the tool and input, not the call,
  // so it matches the asking call with the same input, else the only one asking for that tool
  if (ev === 'classic.PermissionRequest' && ph === 'exit' && !r?.decision && !r?.block) {
    const asks = Object.entries(m.asking)
    const same = asks.filter(([, a]) => a.tool === e?.tool_name)
    const hit = same.find(([, a]) => a.input === digest(JSON.stringify(e?.tool_input))) ?? (same.length === 1 ? same[0] : undefined)
    if (!hit) return false
    const { [hit[0]]: _, ...rest } = m.asking
    m.asking = rest
    m.waits = { ...m.waits, [hit[0]]: hit[1].text }
    return true
  }
  if (ev === 'tool.call') return toolCall(m, x)
  if (ev === 'prompt.context' && ph === 'exit') {
    const files: any[] = r?.instructionFiles ?? e?.instructionFiles ?? []
    for (const f of files) addSource(m, { key: `i:${f.path}`, group: 'instructions', label: String(f.path).split('/').slice(-2).join('/'), note: 'loaded', t })
    return files.length > 0
  }
  if (ev === 'prompt.attachment' && ph === 'exit' && !e?.agentId) return attachment(m, String(e?.type ?? ''), r ? r.text : e?.text, t)
  if (ev === 'session.measure' && ph === 'enter') {
    const c = e?.context ?? {}
    m.context = { percent: c.percent, window: c.window, tokens: c.tokens }
    m.onPlan = Array.isArray(e?.rateLimits) && e.rateLimits.length > 0
    if (typeof e?.cost?.usd === 'number') m.cost = e.cost.usd
    return true
  }
  if (ev === 'session.compact' && ph === 'exit' && !e?.agentId && r && !r.skip && Array.isArray(r.messages) && e?.trigger !== 'precompute') {
    m.compactions++
    m.turnTokens = [] // the window shrank: growth measured before the summary says nothing about after it
    // the summary is the first message of what the compaction leaves; there is no separate summary string
    m.summary = scrub(String(r.messages[0]?.text ?? '')).slice(0, 4000) || undefined
    m.est = { conversation: r.messages.reduce((s: number, msg: any) => s + String(msg?.text ?? '').length, 0), files: 0, results: 0 }
    m.sources = m.sources.filter(s => s.key !== 'summary').map(s => s.group === 'files' ? { ...s, note: 'earlier' as const } : s)
    addSource(m, { key: 'summary', group: 'conversation', label: 'Earlier conversation summary', note: 'summary', t })
    return true
  }
  return false
}

function toolCall(m: SessionModel, { ph, who, e, r, t }: Seen): boolean {
  const tool = String(e?.tool ?? '')
  const id = String(e?.tool_use_id ?? '')
  // Claude's own call in the main conversation: only its result is in the context. A subagent's call (agentId) or another
  // plugin's $.tool.call still adds changes and checks
  const main = !e?.agentId && who === 'claude'
  if (ph === 'enter') {
    if (tool === 'AskUserQuestion') m.waits = { ...m.waits, [id]: questionOf(e) }
    if (e?.agentId && agentDid(m, e.agentId, a => ({ ...a, doing: doingOf(tool, e), calls: a.calls + 1 }))) return true
    return tool === 'AskUserQuestion'
  }
  let changed = false
  if (id in m.waits) { const { [id]: _, ...rest } = m.waits; m.waits = rest; changed = true }
  if (id in m.asking) { const { [id]: _, ...rest } = m.asking; m.asking = rest }
  if (!r || r.deny) return changed
  const text = String(r.text ?? '')
  const kind = kindOf(tool)
  if (main && kind === 'Look') m.est.files += text.length
  else if (main) m.est.results += text.length
  if (kind === 'Change' && !r.isError && !r.result?.staged) {
    const path = String(r.result?.filePath ?? pathOf(e))
    if (path) {
      addFile(m, { path, isNew: tool === 'Write' && r.result?.type === 'create', t, hunks: hunksOf(r.result) })
      m.lastEdit = t
      if (main) {
        m.est.files += String(e?.content ?? e?.new_string ?? e?.new_source ?? '').length // what Claude wrote is in the window too
        addSource(m, { key: `f:${path}`, group: 'files', label: path, note: 'full', t })
      }
    }
  }
  if (main && tool === 'Read' && !r.isError) {
    const path = pathOf(e)
    if (path) addSource(m, { key: `f:${path}`, group: 'files', label: path, note: e?.offset != null || e?.limit != null ? 'excerpt' : 'full', t })
  }
  if (tool === 'Bash') {
    const cmd = String(e?.command ?? '')
    const c = checkIn(cmd)
    if (c) {
      const i = insightOf(cmd, text)
      // a pipeline or a `;` list exits with its last program's code: a check piped into tail, or followed by another
      // command, is judged by what its output says instead
      const ok = c.isLast ? !r.isError && !(i.exit && i.exit > 0) : !text.replace(ANSI, '').split('\n').some(l => c.fail.test(l))
      const kept = scrub(cmd).slice(0, 200)
      m.checks = [{ name: c.name, ok, line: ok ? '' : i.text, t, cmd: kept, ...(rerunnable(cmd, kept) ? { canRerun: true as const } : {}) }, ...m.checks.filter(x => x.name !== c.name)]
    }
  }
  return true
}

// A check the pane may run again: the command is the check alone (after one `cd <dir> &&`), sets no variable that may
// hold a secret, and is stored exactly as typed. `npm test && rm -rf dist` is never offered: a rerun would remove dist too
function rerunnable(cmd: string, kept: string): boolean {
  return kept === cmd && progsOf(cmd).length === 1 && !/(^|\s)\w+=/.test(noCd(cmd))
}

// One of this session's subagents changed; false when the id is none of them (a teammate, another plugin's agent)
function agentDid(m: SessionModel, id: string, f: (a: Agent) => Agent): boolean {
  const i = m.agents.findIndex(a => a.id === id)
  if (i < 0) return false
  m.agents = m.agents.map((a, j) => j === i ? f(a) : a)
  return true
}

// Engine notes about one file, named in their first line: what they say about that file's place in the context
const FILE_NOTE: Record<string, [SourceNote, RegExp]> = {
  edited_text_file: ['changed', /^Note: (.+?) changed on disk/],
  compact_file_reference: ['unrestored', /^Note: (.+?) was read before/],
  read_truncation_notice: ['excerpt', /(\/\S+)/], // the first absolute path the notice names
  file: ['full', /"file_path":"([^"]+)"/],
}
// text undefined: the chain left it out of the request, so it never entered the context
function attachment(m: SessionModel, type: string, text: string | undefined, t: number): boolean {
  if (!text) return false
  if (type === 'nested_memory') {
    m.est.files += text.length
    const p = text.match(/^Contents of (.+?):?$/m)?.[1]
    if (p) addSource(m, { key: `i:${p}`, group: 'instructions', label: p.split('/').slice(-2).join('/'), note: 'loaded', t })
    return !!p
  }
  const n = FILE_NOTE[type]
  if (!n) { m.est.conversation += text.length; return false } // reminders and listings: counted, not listed
  m.est.files += text.length
  const p = text.match(n[1])?.[1]
  if (!p) return false
  addSource(m, { key: `f:${p}`, group: 'files', label: p, note: n[0], t })
  return true
}

// Files a shell command changed, from a list of absolute paths written outside the engine; merged as Edited, since a
// command's edits carry no diff and no create flag. Returns whether any were new to the list
export function mergeShellEdits(m: SessionModel, paths: string[], t: number): boolean {
  let added = false
  for (const p of paths.map(s => s.trim()).filter(s => s.startsWith('/'))) {
    // a file already listed is still a fresh change: the checks run before it say nothing about it now
    if (t > m.lastEdit) { m.lastEdit = t; added = true }
    if (m.files.some(f => f.path === p)) continue
    addFile(m, { path: p, isNew: false, t, byShell: true })
    added = true
  }
  return added
}

// === READINGS ===
export type Status = { kind: 'new' | 'working' | 'input' | 'failed' | 'review' | 'idle'; label: string; detail?: string }
type Check = SessionModel['checks'][number]
// fresh: run since the last change, so its verdict holds; stale: run before it, so it says nothing about the code now
export function splitChecks(m: SessionModel): { fresh: Check[]; stale: Check[] } {
  return { fresh: m.checks.filter(c => c.t >= m.lastEdit), stale: m.checks.filter(c => c.t < m.lastEdit) }
}
const failing = (m: SessionModel) => splitChecks(m).fresh.find(c => !c.ok)

// What 'Right now' says. It is drawn only for what needs the person: a question waiting, a failed check, subagents still
// running. What Claude is doing and what's next are left to the spinner and Claude Code's own todo list
export function statusOf(m: SessionModel): Status {
  const ask = Object.values(m.waits).at(-1)
  if (ask) return { kind: 'input', label: 'Needs your input', detail: ask }
  const bad = failing(m)
  // no dialog is open for a failure: not "needs your input"
  if (bad) return { kind: 'failed', label: m.running ? `${bad.name} failed, Claude is investigating` : `${bad.name} failed`, detail: bad.line }
  if (m.running) return { kind: 'working', label: 'Working' }
  // the turn ended but agents it started in the background go on: not waiting for you yet
  const bg = m.agents.filter(a => a.status === 'running').length
  if (bg) return { kind: 'working', label: `${bg} background agent${bg === 1 ? '' : 's'} working` }
  if (!m.prompts && !m.files.length) return { kind: 'new', label: 'Ready when you are' }
  if (m.ended === 'aborted') return { kind: 'idle', label: 'Stopped', detail: 'You interrupted the last response' }
  if (m.ended === 'error') return { kind: 'idle', label: 'Stopped by an error', detail: 'The last response ended with an error' }
  if (m.ended === 'refusal') return { kind: 'idle', label: 'Stopped', detail: 'Claude declined the last request' }
  // never "Done" or "Ready": a stopped turn with changes proves neither that the work is finished nor that the checks are
  // fresh, so it only says there is something to look at
  if (m.files.length) return { kind: 'review', label: 'Waiting for you', detail: 'Changes available to review' }
  return { kind: 'idle', label: 'Waiting for you' }
}

// Checks as words: never a blank checkmark. line: the verdict of those run since the last change, failures first;
// rerun: the ones run before it, by name, on a line of their own so the doubt is not buried behind a pass. Worded
// "Rerun needed: …" so it reads the same for one name or several
export function checksOf(m: SessionModel): { line: string; failed: boolean; rerun: string } {
  if (!m.checks.length) return { line: m.files.length ? "Checks haven't run yet" : '', failed: false, rerun: '' }
  const { fresh, stale } = splitChecks(m)
  const names = (cs: Check[]) => cs.map(c => c.name).join(', ')
  const bad = fresh.filter(c => !c.ok)
  const good = fresh.filter(c => c.ok)
  const line = [bad.length ? `${names(bad)} failed` : '', good.length ? `${names(good)} passed` : ''].filter(Boolean).join('; ')
  return { line, failed: bad.length > 0, rerun: stale.length ? `Rerun needed: ${names(stale)}` : '' }
}

// Nearly full: past this the pane offers a recap. Set below the point where the engine compacts on its own, so there is
// room to review a recap before a summary happens anyway
export const NEARLY_FULL = 85
export function contextLabel(percent?: number): { label: string; text: string } {
  if (percent == null) return { label: 'Room to begin', text: 'Nothing measured yet: the first response fills this in.' }
  if (percent >= NEARLY_FULL) return { label: 'Nearly full', text: 'Older details will soon be summarised. A recap lets you choose what carries forward.' }
  if (percent >= 50) return { label: 'Filling up', text: 'The conversation and material Claude can use right now.' }
  return { label: 'Plenty of room', text: 'The conversation and material Claude can use right now.' }
}

// The four groups of the expanded bar. Instructions come from the engine's own rows (everything in use but Messages);
// Messages is split by this pane's estimate, then scaled so the three sum to the engine's figure. The gap between the
// unscaled estimate and the engine's Messages row is the confidence shown beside it
export type Segment = { name: string; tokens: number; color: string; isEstimate: boolean }
export const CHARS_PER_TOKEN = 4 // rough for English prose and code; only used to split, never shown as a count
export const CLOSE_ENOUGH = 0.25 // estimate within 25% of the engine's Messages figure reads as "close"
export function segmentsOf(est: Est, rows: readonly { name: string; tokens: number; kind: string }[] | undefined): { segments: Segment[]; confidence: 'close' | 'rough' | 'none'; gap?: number } {
  const used = (rows ?? []).filter(r => r.kind === 'used')
  const msgRow = used.find(r => r.name === 'Messages')
  const instructions = used.filter(r => r !== msgRow).reduce((s, r) => s + r.tokens, 0)
  const raw = [est.conversation, est.files, est.results].map(c => c / CHARS_PER_TOKEN)
  const rawSum = raw.reduce((s, x) => s + x, 0)
  const engine = msgRow?.tokens
  const scale = engine != null && rawSum > 0 ? engine / rawSum : 1
  const [conversation = 0, files = 0, results = 0] = raw.map(x => Math.round(x * scale))
  const segments: Segment[] = [
    { name: 'Instructions', tokens: instructions, color: 'permission', isEstimate: false },
    { name: 'Conversation', tokens: conversation, color: 'claude', isEstimate: true },
    { name: 'Files and references', tokens: files, color: 'planMode', isEstimate: true },
    { name: 'Tool results', tokens: results, color: 'bashBorder', isEstimate: true },
  ]
  if (!engine) return { segments, confidence: 'none' }
  const gap = Math.abs(rawSum - engine) / engine
  return { segments, confidence: gap <= CLOSE_ENOUGH ? 'close' : 'rough', gap }
}

// Turns left before auto-compact: the room to the threshold over the median growth per turn, the median so one big
// file read doesn't swing it. Undefined whenever it can't say (auto-compact off or unread, fewer than two growths seen,
// a window not growing): the pane then shows nothing, never a guessed 0. 0 means the next turn may compact
const TURNS_KEPT = 6
export function recordTurn(m: SessionModel, tokens: number, compactAt: number | undefined): void {
  m.turnTokens = [...m.turnTokens, tokens].slice(-TURNS_KEPT)
  m.compactAt = compactAt
}
export function turnsLeft(m: SessionModel): number | undefined {
  const t = m.turnTokens
  if (m.compactAt == null || t.length < 3) return undefined
  const grew = t.slice(1).map((x, i) => x - t[i]!).sort((a, b) => a - b)
  const mid = grew.length / 2
  const median = grew.length % 2 ? grew[Math.floor(mid)]! : (grew[mid - 1]! + grew[mid]!) / 2
  if (!(median > 0)) return undefined
  const left = Math.floor((m.compactAt - t.at(-1)!) / median)
  return Number.isFinite(left) ? Math.max(0, left) : undefined
}
// The window after each of your turns as a row of block characters, full height at where auto-compact starts (else the
// window's size): how fast it fills, at a glance. Empty under two points
const SPARK = '▁▂▃▄▅▆▇█'
export function sparkOf(m: SessionModel): string {
  const top = m.compactAt ?? m.context.window
  if (m.turnTokens.length < 2 || !top) return ''
  return m.turnTokens.map(t => SPARK[Math.min(SPARK.length - 1, Math.max(0, Math.round((t / top) * SPARK.length) - 1))]).join('')
}
// Claude Code calls it auto-compact; the pane says what happens to you: older messages get summarised
export const compactIn = (left: number) => left === 0 ? 'Summarising any moment' : `Summarising in ~${left} turn${left === 1 ? '' : 's'}`

// === AMBIENT ===
// What the session says while the pane is hidden: only what needs the person, never progress. The band above the prompt
// shows these parts as they stand; a toast announces an alert once, when it appears
export type Part = { text: string; color?: string }
const DOC_FILE = /\.(md|mdx|txt|rst)$/i // a change to prose alone owes no check
const names = (cs: Check[]) => cs.map(c => c.name).join(', ')
export function bandOf(m: SessionModel): Part[] {
  const { fresh, stale } = splitChecks(m)
  const bad = fresh.filter(c => !c.ok)
  const left = turnsLeft(m)
  const p = m.context.percent
  const unchecked = !m.checks.length && m.files.filter(f => !DOC_FILE.test(f.path)).length
  const parts: (Part | undefined)[] = [
    unchecked ? { text: `${unchecked} file${unchecked === 1 ? '' : 's'} changed, no checks run`, color: 'warning' } : undefined,
    bad.length ? { text: `✗ ${names(bad)} failed`, color: 'error' } : undefined,
    stale.length ? { text: `Rerun needed: ${names(stale)}`, color: 'warning' } : undefined,
    p != null && p >= NEARLY_FULL ? { text: `Context ${Math.round(p)}% used: prepare a recap`, color: 'warning' }
      : left != null && left <= 2 ? { text: compactIn(left), color: 'warning' } : undefined,
  ]
  return parts.filter((x): x is Part => !!x)
}
// key -> toast text. A key stays while its alert holds, so a failure that outlives several turns is announced once
export function alertsOf(m: SessionModel): Map<string, string> {
  const out = new Map<string, string>()
  for (const c of splitChecks(m).fresh) if (!c.ok) out.set(`fail:${c.name}`, `${c.name} failed: /session-pane shows what failed`)
  const p = m.context.percent
  if (p != null && p >= NEARLY_FULL) out.set('full', `Context ${Math.round(p)}% used: /session-pane can prepare a recap before older messages are summarised`)
  return out
}

// === RESTORE ===
// What $.store keeps per session: the model less its diffs (the store is small; a diff is the transcript's to keep)
// A subagent running when the snapshot was taken is stopped by the time anything restores it: a restart ends it
export const snapshotOf = (m: SessionModel): SessionModel => ({ ...m, files: m.files.map(({ hunks, ...f }) => f), running: false, waits: {}, asking: {},
  agents: m.agents.map(a => a.status === 'running' ? { ...a, status: 'stopped' as const, doing: undefined } : a) })

// A resumed session with no snapshot: rebuilt from the transcript. Prompts, tool calls and their stored results, in order;
// what the transcript does not hold (the context fill, permission waits) stays empty until the next event
export function replay(m: SessionModel, msgs: readonly { role: string; text: string; toolUses?: readonly any[]; toolResults?: readonly unknown[] }[]): void {
  let t = 1
  for (const msg of msgs) {
    // a user row that opens with a tag is the engine's (a command's output, a reminder), not something you typed
    if (msg.role === 'user' && !msg.toolResults?.length && msg.text && !/^\s*</.test(msg.text)) reduce(m, { ev: 'prompt.submit', ph: 'exit', who: 'you', e: { text: msg.text }, t: t++ })
    if (msg.role !== 'assistant') continue
    m.est.conversation += msg.text.length
    for (const u of msg.toolUses ?? []) {
      const e = { ...u.input, tool: u.tool, tool_use_id: u.tool_use_id }
      if (u.text != null || u.result != null) reduce(m, { ev: 'tool.call', ph: 'exit', who: 'claude', e, r: { result: u.result, text: u.text, ...(u.isError ? { isError: true } : {}) }, t: t++ })
    }
  }
}

// === GOAL ===
// The goal's title until the small model answers, and when it can't: the prompt's first sentence, cut at a word
export function titleOf(text: string, words = 6): string {
  const s = oneLine(text).split(/(?<=[.!?])\s/)[0]!.replace(/[.!?]+$/, '')
  const w = s.split(' ')
  return w.length > words ? `${w.slice(0, words).join(' ')}…` : s
}

// A message that may move the goal: any before the goal is condensed, after that only one of three words or more. "yes",
// "go on", "do it" never cost a call
export const goalWorthy = (m: SessionModel, text: string) => !m.goal || m.goal.isDraft || text.trim().split(/\s+/).length >= 3

// One call condenses every message sent since the last one (the pane asks only while it is open), so it is kept short:
// a terse system prompt, messages clipped, a small answer
export const GOAL_SYSTEM = `Track what a person wants done in a coding session. Reply with JSON only:
{"changed":bool,"title":str,"keep":[str],"done":str}
changed: these messages set or replace the goal. title: the goal in at most 6 words, sentence case, no full stop; repeat the current one when unchanged.
keep: constraints stated in these messages, each under 8 words; [] if none. done: what finished looks like, one short sentence; "" if unclear.`
export const GOAL_TOKENS = 150
const GOAL_CHARS = 3000 // of the messages, newest kept: enough to say what is wanted

export function goalPrompt(m: SessionModel, texts: string[]): string {
  const g = m.goal
  const now = g && !g.isDraft ? `Current goal: ${g.title}` : 'No goal yet.'
  let room = GOAL_CHARS
  const kept = texts.slice().reverse().map(t => { const c = t.slice(0, Math.max(0, room)); room -= c.length; return c }).filter(Boolean).reverse()
  return `${now}\n${kept.map(t => `<message>${t}</message>`).join('\n')}`
}

const MAX_KEEP = 8 // the goal's constraints: the newest, a list one reads at a glance
// Folds the small model's reply into the goal. from: which message it was ("Your opening message", "Your message 3").
// Returns whether the goal changed
export function applyGoal(m: SessionModel, reply: string, text: string, from: string): boolean {
  let j: any
  try { j = JSON.parse(reply.match(/\{[\s\S]*\}/)?.[0] ?? '') } catch { return false }
  if (!j || typeof j.title !== 'string' || !j.title.trim()) return false
  const keep = (Array.isArray(j.keep) ? j.keep : []).filter((k: unknown) => typeof k === 'string' && k.trim()).map((k: string) => ({ text: scrub(clip(k.trim(), 80)), from }))
  const title = scrub(clip(j.title.trim().replace(/\.$/, ''), 60))
  const done = typeof j.done === 'string' && j.done.trim() ? scrub(clip(j.done.trim(), 200)) : undefined
  if (!m.goal || m.goal.isDraft || j.changed === true) {
    const opening = !m.goal || m.goal.isDraft
    m.goal = { title, keep: [...(opening ? [] : m.goal?.keep ?? []), ...keep].slice(-MAX_KEEP), done: done ?? m.goal?.done, from: opening ? m.goal?.from ?? from : from, text: opening ? m.goal?.text ?? text : scrub(text).slice(0, 2000), isDraft: false }
    return true
  }
  if (!keep.length) return false
  m.goal = { ...m.goal, keep: [...m.goal.keep, ...keep.filter((k: { text: string }) => !m.goal!.keep.some(x => x.text.toLowerCase() === k.text.toLowerCase()))].slice(-MAX_KEEP) }
  return true
}

// What the pane holds that a summary can drop: the goal and the files changed, folded from events, so a recap drafted
// after an earlier compaction still names them. '' when there is nothing yet
export function recapNotes(m: SessionModel): string {
  const g = m.goal
  return [
    ...(g ? [`Goal: ${g.title}`, ...g.keep.map(k => `Keep in mind: ${k.text}`), ...(g.done ? [`Done when: ${g.done}`] : [])] : []),
    ...(m.files.length ? ['Files changed:', ...m.files.map(f => `- ${f.path}${f.isNew ? ' (new)' : ''}`)] : []),
  ].join('\n')
}

